alter table public.mission_rescue_cases add column if not exists accepted_agency_id uuid references public.agencies(id), add column if not exists accepted_at timestamptz;
create or replace function public.accept_mission_rescue_offer(p_job_id uuid) returns jsonb language plpgsql security definer set search_path=public set row_security=off as $$ declare v_case public.mission_rescue_cases; v_agency uuid; begin select agency_id into v_agency from public.agency_members where user_id=auth.uid() and status='active' limit 1; select * into v_case from public.mission_rescue_cases where job_id=p_job_id and status='open' limit 1; if v_case.id is null then raise exception 'RESCUE_CASE_NOT_OPEN'; end if; if v_agency is null or v_agency is distinct from v_case.offered_agency_id then raise exception 'RESCUE_OFFER_NOT_FOR_YOUR_AGENCY'; end if; if not exists(select 1 from public.agencies where id=v_agency and status='approved') or not exists(select 1 from public.guards where agency_id=v_agency and availability='available') then raise exception 'BACKUP_CAPACITY_NO_LONGER_AVAILABLE'; end if; update public.mission_rescue_cases set accepted_agency_id=v_agency,accepted_at=now() where id=v_case.id returning * into v_case; insert into public.mission_events(job_id,actor_user_id,event_type,payload) values(p_job_id,auth.uid(),'operations_rescue_backup_accepted',jsonb_build_object('rescue_case_id',v_case.id,'backup_agency_id',v_agency)); return to_jsonb(v_case); end $$; revoke all on function public.accept_mission_rescue_offer(uuid) from public,anon; grant execute on function public.accept_mission_rescue_offer(uuid) to authenticated;
